export const WHISPER_COUNT = 524;

export function getWhispersByDimension(dim: DimensionCode): WhisperUnit[] {
  return wvWhispers.filter(
    (w) => w.relatedDimensions && w.relatedDimensions.includes(d),
  );
}

export function getWhispersByScene(scene: SceneCode): WhisperUnit[] {
  return wvWhispers.filter((w) => w.relatedScene === scene);
}

export function selectPersonalWhispers(
  topDimensions: DimensionCode[],
  currentScene?: SceneCode,
  careerStage?: string,
  count = 3,
): WhisperUnit[] {
  const scored = wvWhispers.map((w) => {
    let score = 0;
    if (w.relatedDimensions) {
      const matches = w.relatedDimensions.filter((d) => topDimensions.includes(d)).length;
      score += matches * 10;
    }
    if (currentScene && w.relatedScene === currentScene) {
      score += 15;
    }
    if (careerStage && w.careerStage === careerStage) {
      score += 8;
    }
    return { whisper: w, score };
  });
  scored.sort((a, b) => b.score - a.score);
  return scored.slice(0, count).map((s) => s.whisper);
}

export function validateWhispers(): { total: number; valid: boolean } {
  return { total: wvWhispers.length, valid: wvWhispers.length >= 450 };
}
